window.savePaceEdit = function () {
    if (!window.editingPaceId) return;
    const goal = window.paceGoals.find(g => g.id === window.editingPaceId);
    if (!goal) return;

    const startStr = document.getElementById('edit-pace-start').value;
    const deadStr = document.getElementById('edit-pace-date').value;
    if (!startStr || !deadStr) return showToast("Both dates are required", "error");
    if (new Date(deadStr) <= new Date(startStr)) return showToast("Deadline must be after start date", "error");

    if (goal.type === 'global') {
        const subjCheckboxes = document.querySelectorAll('.edit-pace-subject-cb:checked');
        const secCheckboxes = document.querySelectorAll('.edit-pace-sec-cb:checked');

        const selectedSubjects = Array.from(subjCheckboxes).map(cb => cb.value).filter(sub => {
            const wasAlreadyInGoal = goal.subjects && goal.subjects.includes(sub);
            if (wasAlreadyInGoal) return true;
            const sObj = window.getAllSubjects ? window.getAllSubjects().find(s => s.subject === sub) : null;
            const progName = sObj ? sObj.program : '';
            const isPassed = Boolean(window.passedItems && ((window.passedItems.subjects && window.passedItems.subjects.includes(sub)) || (window.passedItems.programs && window.passedItems.programs.includes(progName))));
            return !isPassed;
        });
        const selectedSec = Array.from(secCheckboxes).map(cb => cb.value);

        goal.subjects = selectedSubjects;
        goal.secondaryPaces = selectedSec;
    } else if (goal.type !== 'global') {
        const name = document.getElementById('edit-pace-name').value.trim();
        if (!name) return showToast("Goal name is required.", "error");

        const checkboxes = document.querySelectorAll('.edit-pace-cb:checked');
        const selectedItems = Array.from(checkboxes).map(cb => cb.value);

        if (selectedItems.length === 0) return showToast("Please select at least one item.", "error");

        goal.target = name;
        const previousSubjects = goal.subjects || (goal.type === 'subject' ? [goal.target] : []);
        const previousPrograms = goal.programs || (goal.type === 'program' ? [goal.target] : []);

        goal.type = 'bundle';
        delete goal.subjects;
        delete goal.programs;

        const firstItem = selectedItems[0];
        let isProg = false;
        window.tracks.forEach(track => {
            if (window.customPrograms[track.id] && window.customPrograms[track.id].some(p => (p.name || p) === firstItem)) {
                isProg = true;
            }
        });

        if (isProg) {
            goal.programs = selectedItems.filter(pName => {
                const wasAlreadyInGoal = previousPrograms.some(sp => (sp.name || sp) === pName);
                if (wasAlreadyInGoal) return true;
                const isPassed = Boolean(window.passedItems && window.passedItems.programs && window.passedItems.programs.includes(pName));
                return !isPassed;
            });
        } else {
            goal.subjects = selectedItems.filter(sub => {
                const wasAlreadyInGoal = previousSubjects.includes(sub);
                if (wasAlreadyInGoal) return true;
                const sObj = window.getAllSubjects ? window.getAllSubjects().find(s => s.subject === sub) : null;
                const progName = sObj ? sObj.program : '';
                const isPassed = Boolean(window.passedItems && ((window.passedItems.subjects && window.passedItems.subjects.includes(sub)) || (window.passedItems.programs && window.passedItems.programs.includes(progName))));
                return !isPassed;
            });
        }
    }

    goal.startDate = startStr;
    goal.deadline = deadStr;
    FirebaseService.saveToCloud(); renderUI(); closeModal('edit-pace-modal'); showToast("Pace Goal timeline updated!", "success");
};

window.toggleModalDay = function (taskIdOrDate, typeKey, evt) {
    if (!taskIdOrDate || !typeKey) return;

    let taskIndex = AppState.tasks.findIndex(t => t && (String(t.id) === String(taskIdOrDate) || t.date === taskIdOrDate));
    let newState = true;
    let taskDateStr = '';

    if (taskIndex === -1 && typeof taskIdOrDate === 'string' && taskIdOrDate.trim()) {
        const dObj = Utils.parseDateSafe(taskIdOrDate);
        if (dObj && !isNaN(dObj.getTime())) {
            const existingTask = window.getTaskForDate(dObj);
            if (existingTask) {
                taskIndex = AppState.tasks.indexOf(existingTask);
                if (taskIndex > -1) {
                    newState = !Boolean(AppState.tasks[taskIndex][typeKey]);
                    AppState.tasks[taskIndex][typeKey] = newState;
                    taskDateStr = AppState.tasks[taskIndex].date || Utils.formatDate(dObj);
                }
            } else {
                const dateStr = Utils.formatDate(dObj);
                const isoDate = `${dObj.getFullYear()}-${String(dObj.getMonth() + 1).padStart(2, '0')}-${String(dObj.getDate()).padStart(2, '0')}`;
                taskDateStr = dateStr;
                const newTask = {
                    id: 'task_' + isoDate + '_' + Date.now().toString(36),
                    date: dateStr,
                    note: '',
                    updatedAt: Date.now() + (window.serverTimeOffset || 0)
                };
                if (Array.isArray(window.customActions)) {
                    window.customActions.forEach(a => { newTask[a.id] = false; });
                }
                newTask[typeKey] = true;
                newState = true;
                AppState.tasks.push(newTask);
                taskIndex = AppState.tasks.length - 1;
            }
        }
    } else if (taskIndex > -1) {
        newState = !Boolean(AppState.tasks[taskIndex][typeKey]);
        AppState.tasks[taskIndex][typeKey] = newState;
        taskDateStr = AppState.tasks[taskIndex].date || '';
    }

    if (taskIndex > -1) {
        const updatedTask = AppState.tasks[taskIndex];
        updatedTask.updatedAt = Date.now() + (window.serverTimeOffset || 0);
        AppState.isLocalDirty = true;

        if (AppState._tasksDateMap) {
            if (updatedTask.id) AppState._tasksDateMap.set(String(updatedTask.id), updatedTask);
            if (updatedTask.date) {
                AppState._tasksDateMap.set(updatedTask.date, updatedTask);
                const d = Utils.parseDateSafe(updatedTask.date);
                if (d && !isNaN(d.getTime())) {
                    const isoKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
                    AppState._tasksDateMap.set(isoKey, updatedTask);
                }
            }
        }

        // 1. Instant Optimistic DOM Update — target ONLY the exact clicked button via event
        const evtTarget = (evt && evt.target) || (window.event && window.event.target) || null;
        const clickedBtn = evtTarget ? evtTarget.closest('button[onclick*="toggleModalDay"]') : null;
        if (clickedBtn) {
            const isHeatmapSquare = clickedBtn.hasAttribute('data-datekey');
            if (isHeatmapSquare) {
                const actionObj = (window.customActions || []).find(a => a.id === typeKey);
                const cMap = actionObj ? (AppState.twColors[actionObj.color] || AppState.twColors['blue']) : AppState.twColors['blue'];
                const hexColor = (cMap && cMap.hex) || '#10b981';

                if (newState) {
                    clickedBtn.style.backgroundColor = hexColor;
                    clickedBtn.style.borderColor = hexColor;
                    clickedBtn.style.boxShadow = `0 0 6px ${hexColor}55`;
                    clickedBtn.className = clickedBtn.className.replace(/bg-slate-[^\s]+/g, '').replace(/border-slate-[^\s]+/g, '');
                    clickedBtn.innerHTML = `<svg class="w-2 h-2 sm:w-2.5 sm:h-2.5 text-white pointer-events-none drop-shadow-sm" fill="none" stroke="currentColor" stroke-width="3" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/></svg>`;
                    clickedBtn.setAttribute('data-done', 'true');
                    clickedBtn.setAttribute('data-status', 'Completed (YES)');
                } else {
                    clickedBtn.style.backgroundColor = '';
                    clickedBtn.style.borderColor = '';
                    clickedBtn.style.boxShadow = '';
                    clickedBtn.innerHTML = `<span class="w-1 h-1 rounded-full bg-slate-300 dark:bg-slate-600/70 pointer-events-none"></span>`;
                    clickedBtn.setAttribute('data-done', 'false');
                    clickedBtn.setAttribute('data-status', 'Missed (NO)');
                }
            } else {
                if (newState) {
                    clickedBtn.classList.remove('from-red-400', 'to-red-500', 'shadow-[0_2px_8px_rgba(239,68,68,0.4)]');
                    clickedBtn.classList.add('from-green-400', 'to-emerald-500', 'shadow-[0_2px_8px_rgba(16,185,129,0.4)]');
                    if (clickedBtn.title) clickedBtn.title = clickedBtn.title.replace(': NO', ': YES');
                } else {
                    clickedBtn.classList.remove('from-green-400', 'to-emerald-500', 'shadow-[0_2px_8px_rgba(16,185,129,0.4)]');
                    clickedBtn.classList.add('from-red-400', 'to-red-500', 'shadow-[0_2px_8px_rgba(239,68,68,0.4)]');
                    if (clickedBtn.title) clickedBtn.title = clickedBtn.title.replace(': YES', ': NO');
                }
            }
            clickedBtn.classList.add('scale-110');
            setTimeout(() => clickedBtn.classList.remove('scale-110'), 120);
        }

        // If today was updated, also update today's buttons optimistically
        const today = new Date();
        const taskD = getTaskDate(updatedTask);
        const isToday = taskD && !isNaN(taskD.getTime()) &&
            taskD.getFullYear() === today.getFullYear() &&
            taskD.getMonth() === today.getMonth() &&
            taskD.getDate() === today.getDate();

        if (isToday) {
            const actionObj = (window.customActions || []).find(a => a.id === typeKey);
            const cMap = actionObj ? (AppState.twColors[actionObj.color] || AppState.twColors['blue']) : AppState.twColors['blue'];
            const cardEl = document.getElementById(`daily-action-card-${typeKey}`);
            const btnYes = document.getElementById(`btn-action-yes-${typeKey}`);
            const btnNo = document.getElementById(`btn-action-no-${typeKey}`);

            if (cardEl) {
                cardEl.className = `bg-white dark:bg-slate-800 p-5 md:p-6 rounded-3xl md:rounded-[2rem] shadow-sm flex flex-col transition-all duration-300 min-h-[300px] border-2 ${newState === true ? cMap.border + ' shadow-lg' : (newState === false ? 'border-red-500 shadow-lg shadow-red-500/10' : 'border-slate-200 dark:border-slate-700')}`;
            }
            if (btnYes && btnNo) {
                if (newState === true) {
                    btnYes.className = 'flex-1 py-1.5 sm:py-2 md:py-2.5 text-[9px] sm:text-[10px] md:text-xs font-black uppercase tracking-widest transition-all duration-300 active:scale-90 bg-gradient-to-br from-green-400 to-emerald-500 text-white shadow-[0_4px_12px_rgba(16,185,129,0.5)] scale-105';
                    btnNo.className = 'flex-1 py-1.5 sm:py-2 md:py-2.5 text-[9px] sm:text-[10px] md:text-xs font-black uppercase tracking-widest transition-all duration-300 active:scale-90 bg-slate-100 dark:bg-slate-700 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-600';
                } else if (newState === false) {
                    btnYes.className = 'flex-1 py-1.5 sm:py-2 md:py-2.5 text-[9px] sm:text-[10px] md:text-xs font-black uppercase tracking-widest transition-all duration-300 active:scale-90 bg-slate-100 dark:bg-slate-700 text-slate-400 hover:bg-slate-200 dark:hover:bg-slate-600';
                    btnNo.className = 'flex-1 py-1.5 sm:py-2 md:py-2.5 text-[9px] sm:text-[10px] md:text-xs font-black uppercase tracking-widest transition-all duration-300 active:scale-90 bg-gradient-to-br from-red-400 to-red-500 text-white shadow-[0_4px_12px_rgba(239,68,68,0.4)] scale-105';
                }
            }

            const dashBtn = document.getElementById(`dashboard-daily-action-btn-${typeKey}`);
            if (dashBtn) {
                const isActive = newState === true;
                const activeStyle = `background-color: ${cMap.hex}; border-color: ${cMap.hex}; color: white; box-shadow: 0 4px 12px ${cMap.hex}33;`;
                dashBtn.className = isActive
                    ? `flex flex-col justify-between p-2 sm:p-2.5 rounded-2xl border font-black transition-all duration-300 active:scale-95 text-left w-full h-full min-h-[58px] text-white border-transparent`
                    : 'flex flex-col justify-between p-2 sm:p-2.5 rounded-2xl border font-black transition-all duration-300 active:scale-95 text-left w-full h-full min-h-[58px] bg-slate-50 dark:bg-slate-900/40 text-slate-600 dark:text-slate-400 border-slate-200 dark:border-slate-700/80 hover:bg-slate-100 dark:hover:bg-slate-900/60';
                dashBtn.style.cssText = isActive ? activeStyle : '';

                const statusText = dashBtn.querySelector('.dashboard-action-status-text');
                if (statusText) statusText.textContent = isActive ? 'YES' : 'NO';

                const badge = dashBtn.querySelector('.dashboard-action-badge');
                if (badge) {
                    badge.innerHTML = isActive
                        ? `<span class="flex h-4 w-4 rounded-full bg-white text-emerald-500 items-center justify-center shadow-sm text-[8px] font-black">✓</span>`
                        : `<span class="flex h-4 w-4 rounded-full border border-slate-300 dark:border-slate-700 bg-white dark:bg-slate-800 text-slate-400 dark:text-slate-500 items-center justify-center text-[7px] font-black">✕</span>`;
                }

                const iconContainer = dashBtn.querySelector('.p-1.rounded-lg');
                if (iconContainer) {
                    iconContainer.className = `p-1 rounded-lg ${isActive ? 'bg-white/20 text-white' : cMap.iconBg + ' ' + cMap.text + ' ' + cMap.borderLt + ' border'} shrink-0`;
                }

                const trackBadge = dashBtn.querySelector('.dashboard-action-track-badge');
                if (trackBadge) {
                    trackBadge.className = `dashboard-action-track-badge inline-block px-1 rounded-[3px] text-[6px] font-black uppercase tracking-widest ${isActive ? 'bg-white/20 text-white' : 'bg-slate-200 dark:bg-slate-700 text-slate-500 dark:text-slate-300'}`;
                }
            }

            // Update Progress Bar
            let c = 0;
            (window.customActions || []).forEach(a => { if (updatedTask[a.id]) c++; });
            const dailyPct = (window.customActions && window.customActions.length > 0) ? Math.round((c / window.customActions.length) * 100) : 0;
            const bar = document.getElementById('daily-actions-progress');
            if (bar) {
                bar.style.width = dailyPct + '%';
                safeSetText('daily-actions-percent', dailyPct + '%');
                let clr = 'bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)]';
                if (dailyPct >= 25) clr = 'bg-orange-500 shadow-[0_0_15px_rgba(249,115,22,0.8)]';
                if (dailyPct >= 50) clr = 'bg-yellow-400 shadow-[0_0_15px_rgba(250,204,21,0.8)]';
                if (dailyPct >= 75) clr = 'bg-lime-500 shadow-[0_0_15px_rgba(132,204,22,0.8)]';
                if (dailyPct === 100) clr = 'bg-green-500 shadow-[0_0_15px_rgba(34,197,94,0.8)]';
                bar.className = `h-full rounded-full transition-all duration-500 ease-out ${clr}`;
            }
            const dashPercent = document.getElementById('dashboard-daily-actions-percent');
            const dashBar = document.getElementById('dashboard-daily-actions-progress');
            if (dashPercent && dashBar) {
                dashPercent.textContent = dailyPct + '%';
                dashBar.style.width = dailyPct + '%';
                let clr = 'bg-red-500';
                if (dailyPct >= 25) clr = 'bg-orange-500';
                if (dailyPct >= 50) clr = 'bg-yellow-400';
                if (dailyPct >= 75) clr = 'bg-lime-500';
                if (dailyPct === 100) clr = 'bg-green-500';
                dashBar.className = `h-full rounded-full transition-all duration-500 ease-out ${clr}`;
            }
        }

        // Instant The X Commitments Habit Radar & Trend Line Charts sync
        if (typeof window.renderSpectraCommitmentsChart === 'function') {
            window.renderSpectraCommitmentsChart();
        }
        if (typeof renderTrendCharts === 'function') {
            renderTrendCharts();
        }
        const dbModalSync = document.getElementById('daily-actions-db-modal');
        if (dbModalSync && !dbModalSync.classList.contains('hidden') && typeof window.openDailyActionsDBModal === 'function') {
            window.openDailyActionsDBModal();
        }

        // 2. Broadcast to other open browser tabs for <2ms instant sync
        if (window.X29SyncChannel) {
            try {
                window.X29SyncChannel.postMessage({
                    type: 'DAILY_ACTION_UPDATE',
                    actionId: typeKey,
                    taskIdOrDate: taskIdOrDate,
                    newState: newState,
                    timestamp: Date.now()
                });
            } catch(e) {}
        }

        // 3. Realtime Cross-Device Cloud Synchronization (auto-batched Firestore write)
        if (window.FirebaseService && typeof window.FirebaseService.saveToCloud === 'function') {
            window.FirebaseService.saveToCloud(false);
        }

        // 4. Schedule debounced full UI & chart updates for 60 FPS performance during fast clicks
        if (window._gridToggleDebounce) clearTimeout(window._gridToggleDebounce);
        window._gridToggleDebounce = setTimeout(() => {
            requestAnimationFrame(() => {
                if (typeof renderTrendCharts === 'function') renderTrendCharts();
                if (typeof window.renderSpectraCommitmentsChart === 'function') window.renderSpectraCommitmentsChart();
                const modal = document.getElementById('analytics-modal');
                if (modal && !modal.classList.contains('hidden') && typeof populateAnalyticsModal === 'function') populateAnalyticsModal(typeKey);
                const dbModal = document.getElementById('daily-actions-db-modal');
                if (dbModal && !dbModal.classList.contains('hidden') && typeof window.openDailyActionsDBModal === 'function') window.openDailyActionsDBModal();
            });
        }, 120);
    }
};

window.openEditModal = function (taskId, type, subTaskId = null) {
    let taskIndex = typeof taskId === 'number' ? AppState.tasks.findIndex(t => t.id === taskId) : -1;
    const key = type + 'Tasks';

    // If it was an unscheduled task (e.g. unsched-...), slot it first or locate it
    if (taskIndex === -1 && subTaskId && typeof subTaskId === 'string' && subTaskId.startsWith('unsched-')) {
        const parts = subTaskId.split('-');
        const chNum = parts[parts.length - 1];
        const subId = parts.slice(2, parts.length - 1).join('-');
        const sObj = window.getAllSubjects().find(s => s.subject.replace(/[^a-zA-Z0-9]/g, '-') === subId);
        const subj = sObj ? sObj.subject : subId;
        const formattedCh = `Ch. ${chNum}`;

        ensureAvailableSlots(1, type, 0);
        for (let i = 0; i < AppState.tasks.length; i++) {
            if (AppState.tasks[i].type === 'study' && Array.isArray(AppState.tasks[i][key])) {
                const bIdx = AppState.tasks[i][key].findIndex(b => b.subject === 'Revision');
                if (bIdx > -1) {
                    AppState.tasks[i][key][bIdx] = {
                        subject: subj,
                        chapter: formattedCh,
                        title: `Topic ${chNum}`,
                        completed: false,
                        id: AppState.tasks[i][key][bIdx].id
                    };
                    taskIndex = i;
                    taskId = AppState.tasks[i].id;
                    subTaskId = AppState.tasks[i][key][bIdx].id;
                    break;
                }
            }
        }
    }

    if (taskIndex === -1) return;
    const dayTask = AppState.tasks[taskIndex];
    let taskObj = (dayTask[key] || []).find(b => b.id === subTaskId);
    if (!taskObj) return;

    window.editingTask = { taskId, type, subTaskId, oldSubject: taskObj.subject };
    const prog = type;
    const subjSelect = document.getElementById('edit-task-subject');
    subjSelect.innerHTML = '<option value="Revision">Revision (Empty Slot)</option>';

    if (window.customPrograms[prog]) {
        window.customPrograms[prog].forEach(p => {
            const pName = p.name || p;
            const subs = (syllabusStructure[prog] || []).filter(s => s.program === pName);
            if (subs.length > 0) {
                let groupHtml = `<optgroup label="${pName}">`;
                subs.forEach(s => { groupHtml += `<option value="${s.subject}" ${s.subject === taskObj.subject ? 'selected' : ''}>${s.subject}</option>`; });
                groupHtml += `</optgroup>`; subjSelect.innerHTML += groupHtml;
            }
        });
    }

    let chNum = taskObj.chapter.replace('Ch. ', ''); if (taskObj.subject === 'Revision') chNum = '';
    document.getElementById('edit-task-num').value = chNum;
    document.getElementById('edit-task-title').value = taskObj.title === 'Practice' ? '' : taskObj.title;

    const skipBtn = document.getElementById('etm-skip-btn');
    const skipText = document.getElementById('etm-skip-btn-text');
    if (skipBtn && skipText) {
        if (taskObj.subject === 'Revision') {
            skipBtn.classList.add('hidden');
        } else {
            skipBtn.classList.remove('hidden');
            if (taskObj.skipped) {
                skipText.textContent = "Unskip Chapter";
                skipBtn.className = "text-slate-650 dark:text-slate-350 bg-slate-100 hover:bg-slate-200 dark:bg-slate-700/50 hover:dark:bg-slate-700 border border-slate-200 dark:border-slate-700/80 font-black text-[10px] uppercase tracking-widest py-2 px-4 rounded-lg transition-colors flex items-center space-x-1.5 active:scale-95 shadow-sm";
            } else {
                skipText.textContent = "Skip Chapter";
                skipBtn.className = "text-amber-600 hover:text-amber-700 hover:bg-amber-50 dark:hover:bg-amber-900/20 font-black text-[10px] uppercase tracking-widest py-2 px-4 rounded-lg transition-colors flex items-center space-x-1.5 active:scale-95";
            }
        }
    }

    openModal('edit-task-modal');
};

window.toggleSkipTask = function () {
    if (!window.editingTask) return;
    const { taskId, type, subTaskId } = window.editingTask;
    const taskIndex = AppState.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const key = type + 'Tasks';
    if (Array.isArray(AppState.tasks[taskIndex][key])) {
        const bIdx = AppState.tasks[taskIndex][key].findIndex(b => b.id === subTaskId);
        if (bIdx > -1) {
            const isSkipped = !!AppState.tasks[taskIndex][key][bIdx].skipped;
            AppState.tasks[taskIndex][key][bIdx].skipped = !isSkipped;
            if (!isSkipped) {
                AppState.tasks[taskIndex][key][bIdx].completed = false;
                AppState.tasks[taskIndex][key][bIdx].completedAt = null;

                const skippedSub = AppState.tasks[taskIndex][key][bIdx].subject;
                const skippedCh = AppState.tasks[taskIndex][key][bIdx].chapter;

                // 1. Clean up from monthlyTargetsDatabase
                if (window.monthlyTargetsDatabase) {
                    Object.keys(window.monthlyTargetsDatabase).forEach(mKey => {
                        const mList = window.monthlyTargetsDatabase[mKey] || [];
                        for (let i = mList.length - 1; i >= 0; i--) {
                            const mt = mList[i];
                            if (mt.track === type && mt.subject === skippedSub && (mt.chapter === skippedCh || mt.chapter === `Ch. ${skippedCh}`)) {
                                const mtTid = mt.id || window.generateItemId(mt, `monthlyTargetsDatabase_${mKey}`);
                                if (mtTid) window.recordItemDeletion(mtTid);
                                mList.splice(i, 1);
                            }
                        }
                    });
                }

                // 2. Clean up from weeklyTargetsDatabase
                if (window.weeklyTargetsDatabase) {
                    Object.keys(window.weeklyTargetsDatabase).forEach(wKey => {
                        const wList = window.weeklyTargetsDatabase[wKey] || [];
                        for (let i = wList.length - 1; i >= 0; i--) {
                            const wt = wList[i];
                            if (wt.track === type && wt.subject === skippedSub && (wt.chapter === skippedCh || wt.chapter === `Ch. ${skippedCh}`)) {
                                const wtTid = wt.id || window.generateItemId(wt, `weeklyTargetsDatabase_${wKey}`);
                                if (wtTid) window.recordItemDeletion(wtTid);
                                wList.splice(i, 1);
                            }
                        }
                    });
                }

                // 3. Clean up from dailyTargetsDatabase
                if (window.dailyTargetsDatabase) {
                    Object.keys(window.dailyTargetsDatabase).forEach(dKey => {
                        const dList = window.dailyTargetsDatabase[dKey] || [];
                        dList.forEach(dt => {
                            if (dt.track === type && dt.subject === skippedSub && (dt.chapter === skippedCh || dt.chapter === `Ch. ${skippedCh}`)) {
                                dt.isDeleted = true;
                                const dtTid = dt.id || window.generateItemId(dt, `dailyTargetsDatabase_${dKey}`);
                                if (dtTid) window.recordItemDeletion(dtTid);
                            }
                        });
                    });
                }
            }
        }
    }
    recalculateTotals();
    FirebaseService.saveToCloud();
    renderUI();
    closeModal('edit-task-modal');
    showToast("Chapter status updated!", "success");
};

window.saveTaskEdit = function () {
    if (!window.editingTask) return;
    const { taskId, type, subTaskId, oldSubject } = window.editingTask;
    const taskIndex = AppState.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const prog = type;
    const newSubject = document.getElementById('edit-task-subject').value;
    let newNum = document.getElementById('edit-task-num').value;
    let newTitle = document.getElementById('edit-task-title').value;

    if (newSubject === 'Revision') { window.requestDeleteTask(); return; }

    newNum = newNum ? `Ch. ${newNum}` : 'Ch. ?';
    newTitle = newTitle || 'Topic';

    const key = type + 'Tasks';
    if (oldSubject === newSubject) {
        const bIdx = (AppState.tasks[taskIndex][key] || []).findIndex(b => b.id === subTaskId);
        if (bIdx > -1) AppState.tasks[taskIndex][key][bIdx] = { ...tasks[taskIndex][key][bIdx], chapter: newNum, title: newTitle };
        reorderSubjectChapters(prog, newSubject);
    } else {
        if (oldSubject !== 'Revision') { const oldS = (syllabusStructure[prog] || []).find(s => s.subject === oldSubject); if (oldS && oldS.chapters > 0) oldS.chapters--; }
        const bIdx = (AppState.tasks[taskIndex][key] || []).findIndex(b => b.id === subTaskId);
        if (bIdx > -1) AppState.tasks[taskIndex][key][bIdx] = { subject: newSubject, chapter: newNum, title: newTitle, completed: false, id: subTaskId };
        const newS = (syllabusStructure[prog] || []).find(s => s.subject === newSubject); if (newS) newS.chapters++;
        reorderSubjectChapters(prog, oldSubject); reorderSubjectChapters(prog, newSubject);
    }
    recalculateTotals(); FirebaseService.saveToCloud(); renderUI(); closeModal('edit-task-modal'); showToast("Task updated successfully!", "success");
};

window.requestDeleteTask = function () {
    window.openConfirmModal("Clear Task Slot", "Are you sure you want to clear this task? The subsequent schedule will automatically shift up.", window.deleteTask);
};

window.deleteTask = function () {
    if (!window.editingTask) return;
    const { taskId, type, subTaskId, oldSubject } = window.editingTask;
    const taskIndex = AppState.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const prog = type;
    const key = type + 'Tasks';

    if (oldSubject !== 'Revision') { const oldS = (syllabusStructure[prog] || []).find(s => s.subject === oldSubject); if (oldS && oldS.chapters > 0) oldS.chapters--; }
    if (Array.isArray(AppState.tasks[taskIndex][key])) {
        AppState.tasks[taskIndex][key] = AppState.tasks[taskIndex][key].map(b => b.id === subTaskId ? { subject: "Revision", chapter: "Rev", title: "Practice", completed: false, id: b.id } : b);
    }

    if (oldSubject !== 'Revision') {
        let targetSlots = []; let gatheredTasks = [];
        for (let i = 0; i < AppState.tasks.length; i++) {
            if (AppState.tasks[i].type !== 'study') continue;
            if (Array.isArray(AppState.tasks[i][key])) {
                for (let j = 0; j < AppState.tasks[i][key].length; j++) {
                    const bTask = AppState.tasks[i][key][j];
                    if (!bTask.completed && (bTask.subject === oldSubject || (i === taskIndex && bTask.id === subTaskId))) {
                        targetSlots.push({ tIdx: i, bIdx: j });
                        gatheredTasks.push({ ...bTask });
                    }
                }
            }
        }
        // local Utils.extractNum consolidated globally
        gatheredTasks.sort((a, b) => { if (a.subject === 'Revision') return 1; if (b.subject === 'Revision') return -1; return Utils.extractNum(a.chapter) - Utils.extractNum(b.chapter); });
        for (let k = 0; k < targetSlots.length; k++) {
            const slot = targetSlots[k]; const chObj = gatheredTasks[k];
            AppState.tasks[slot.tIdx][key][slot.bIdx] = { ...chObj, id: AppState.tasks[slot.tIdx][key][slot.bIdx].id };
        }
    }
    recalculateTotals(); FirebaseService.saveToCloud(); renderUI(); closeModal('edit-task-modal'); showToast("Task deleted and schedule shifted up.", "success");
};

// --- Configuration & Expansion System Logic ---

window.switchSysTab = function (tab) {
    ['chapter', 'subject', 'program', 'manage', 'priority', 'track'].forEach(t => {
        const btn = document.getElementById(`sys-tab-${t}`);
        const content = document.getElementById(`sys-content-${t}`);
        if (!btn || !content) return;

        if (t === tab) {
            btn.classList.add('bg-blue-600', 'text-white', 'shadow-md'); btn.classList.remove('bg-slate-100', 'dark:bg-slate-700', 'text-slate-500', 'dark:text-slate-400');
            content.classList.remove('hidden');
        } else {
            btn.classList.remove('bg-blue-600', 'text-white', 'shadow-md'); btn.classList.add('bg-slate-100', 'dark:bg-slate-700', 'text-slate-500', 'dark:text-slate-400');
            content.classList.add('hidden');
        }
    });
    if (tab === 'chapter') updateChProgDropdown();
    if (tab === 'subject') updateSubProgDropdown();
    if (tab === 'manage') window.updateManageDropdown();
    if (tab === 'priority') window.renderPriorityConfig();
    if (tab === 'track') window.renderTrackList();
};

window.updateManageDropdown = function () {
    const type = document.getElementById('manage-type').value;
    const targetSelect = document.getElementById('manage-target');
    const trackBox = document.getElementById('manage-track-box');
    const progBox = document.getElementById('manage-program-box');
    targetSelect.innerHTML = '';

    if (type === 'action') {
        trackBox.classList.add('hidden');
        progBox.classList.add('hidden');
        const sortedActions = [...window.customActions].sort((a, b) => (a.priority ?? 999) - (b.priority ?? 999));
        sortedActions.forEach(a => targetSelect.innerHTML += `<option value="${a.id}">${a.title}</option>`);
    } else if (type === 'program') {
        trackBox.classList.remove('hidden');
        progBox.classList.add('hidden');
        const track = document.getElementById('manage-track').value;
        if (window.customPrograms[track]) {
            window.customPrograms[track].forEach(p => {
                const pName = p.name || p;
                targetSelect.innerHTML += `<option value="${pName}">${pName}</option>`;
            });
        }
    } else if (type === 'subject') {
        trackBox.classList.remove('hidden');
        progBox.classList.remove('hidden');
        const track = document.getElementById('manage-track').value;
        const progSelect = document.getElementById('manage-program');
        progSelect.innerHTML = '';
        if (window.customPrograms[track]) {
            window.customPrograms[track].forEach(p => {
                const pName = p.name || p;
                progSelect.innerHTML += `<option value="${pName}">${pName}</option>`;
            });
        }
        window.updateManageSubjects();
    }
};

window.updateManageSubjects = function () {
    const track = document.getElementById('manage-track').value;
    const prog = document.getElementById('manage-program').value;
    const targetSelect = document.getElementById('manage-target');
    targetSelect.innerHTML = '';

    const subs = (syllabusStructure[track] || []).filter(s => s.program === prog).sort((a, b) => (a.priority ?? 999) - (b.priority ?? 999));
    subs.forEach(s => targetSelect.innerHTML += `<option value="${s.subject}">${s.subject}</option>`);
    if (subs.length === 0) targetSelect.innerHTML = '<option value="">No subjects found</option>';
};

window.executeManageEdit = function () {
    const type = document.getElementById('manage-type').value;
    const track = type !== 'action' ? document.getElementById('manage-track').value : null;
    const oldName = document.getElementById('manage-target').value;
    const newName = document.getElementById('manage-new-name').value.trim();

    if (!oldName) return showToast("Please select an item to edit.", "error");
    if (!newName && type !== 'action' && type !== 'program') return showToast("New name cannot be empty.", "error");

    if (type === 'program') {
        let renamed = false;
        if (newName && oldName.toLowerCase() !== newName.toLowerCase()) {
            if (window.customPrograms[track] && window.customPrograms[track].some(p => (p.name || p).toLowerCase() === newName.toLowerCase())) return showToast("Program already exists.", "error");
            renamed = true;
        }

        const pIdx = window.customPrograms[track] ? window.customPrograms[track].findIndex(p => (p.name || p) === oldName) : -1;
        if (pIdx > -1) {
            let progObj = window.customPrograms[track][pIdx];
            if (typeof progObj !== 'object') {
                progObj = {
                    id: oldName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || 'prog-' + pIdx,
                    name: oldName,
                    priority: 3,
                    order: pIdx
                };
                window.customPrograms[track][pIdx] = progObj;
            }

            if (renamed) {
                progObj.name = newName;
            }
        }

        if (renamed) {
            if (syllabusStructure[track]) {
                syllabusStructure[track].forEach(s => { if (s.program === oldName) s.program = newName; });
            }
            if (window.chartVisibility.prog[oldName] !== undefined) { window.chartVisibility.prog[newName] = window.chartVisibility.prog[oldName]; delete window.chartVisibility.prog[oldName]; }

            window.paceGoals.forEach(g => {
                if (g.type === 'program' && g.target === oldName) g.target = newName;
                if (g.type === 'bundle' && g.programs) {
                    const idx = g.programs.indexOf(oldName);
                    if (idx > -1) g.programs[idx] = newName;
                }
            });
            if (window.passedItems.programs.includes(oldName)) {
                window.passedItems.programs = window.passedItems.programs.filter(p => p !== oldName);
                window.passedItems.programs.push(newName);
            }
        }

        // Update rename on existing overall and subject results
        if (window.successResults) {
            window.successResults.forEach(r => {
                if (r.type === 'cgpa' && r.title === (renamed ? newName : oldName)) {
                    if (renamed) {
                        r.title = newName;
                    }
                }
            });
        }

        if (renamed) {
            showToast("Program renamed successfully!", "success");
        } else {
            showToast("No changes made.", "warning");
        }

    } else if (type === 'subject') {
        if (oldName.toLowerCase() === newName.toLowerCase()) return showToast("New name must be different.", "error");
        const isGlobalDuplicate = window.getAllSubjects().some(s => s.subject.toLowerCase() === newName.toLowerCase());
        if (isGlobalDuplicate) return showToast("Subject name must be unique globally.", "error");

        const sObj = syllabusStructure[track] ? syllabusStructure[track].find(s => s.subject === oldName) : null;
        if (sObj) sObj.subject = newName;

        if (AppState.subjectColors[oldName]) AppState.subjectColors[newName] = AppState.subjectColors[oldName];
        for (let i = 0; i < AppState.tasks.length; i++) {
            if (AppState.tasks[i].type !== 'study') continue;
            const key = track + 'Tasks';
            if (Array.isArray(AppState.tasks[i][key])) {
                AppState.tasks[i][key].forEach(b => { if (b.subject === oldName) b.subject = newName; });
            }
        }

        if (AppState.currentFilter === oldName) AppState.currentFilter = newName;
        if (window.chartVisibility.subjects[oldName] !== undefined) { window.chartVisibility.subjects[newName] = window.chartVisibility.subjects[oldName]; delete window.chartVisibility.subjects[oldName]; }

        window.paceGoals.forEach(g => {
            if (g.type === 'subject' && g.target === oldName) g.target = newName;
            if (g.type === 'bundle' && g.subjects) {
                const idx = g.subjects.indexOf(oldName);
                if (idx > -1) g.subjects[idx] = newName;
            }
        });
        if (window.passedItems.subjects.includes(oldName)) {
            window.passedItems.subjects = window.passedItems.subjects.filter(s => s !== oldName);
            window.passedItems.subjects.push(newName);
        }

        showToast("Subject renamed universally!", "success");

    } else if (type === 'action') {
        if (!newName) return showToast("New title cannot be empty.", "error");
        const act = window.customActions.find(a => a.id === oldName);
        if (act) { act.title = newName; showToast("Action title updated!", "success"); }
    }

    document.getElementById('manage-new-name').value = '';
    FirebaseService.saveToCloud(); renderUI(); updateManageDropdown();
};

window.requestManageDelete = function () {
    const targetName = document.getElementById('manage-target').value;
    if (!targetName) return showToast("Please select an item to delete.", "error");
    window.openConfirmModal("Delete Item", `Are you sure you want to completely delete "${targetName}"? This action cannot be undone.`, window.executeManageDelete);
};

window.executeManageDelete = function () {
    const type = document.getElementById('manage-type').value;
    const targetName = document.getElementById('manage-target').value;
    if (!targetName) return showToast("Please select an item to delete.", "error");

    if (type === 'action') {
        if (typeof window.recordItemDeletion === 'function') {
            window.recordItemDeletion(targetName);
            const act = (window.customActions || []).find(a => a.id === targetName || a.name === targetName);
            if (act && act.id) window.recordItemDeletion(act.id);
        }
        window.customActions = window.customActions.filter(a => a.id !== targetName && a.name !== targetName);
        delete window.chartVisibility.monthly[targetName]; delete window.chartVisibility.yearly[targetName];
        showToast(`Action tracker deleted.`, "success");
    } else {
        const track = document.getElementById('manage-track').value;
        if (type === 'program') {
            const subsToDelete = (syllabusStructure[track] || []).filter(s => s.program === targetName).map(s => s.subject);
            if (typeof window.recordItemDeletion === 'function') {
                window.recordItemDeletion(targetName);
                subsToDelete.forEach(sub => window.recordItemDeletion(sub));
                (window.paceGoals || []).filter(g => (g.type === 'program' && g.target === targetName) || (g.type === 'subject' && subsToDelete.includes(g.target))).forEach(g => window.recordItemDeletion(g.id));
                (window.successResults || []).filter(r => r.type === 'cgpa' && r.title === targetName).forEach(r => window.recordItemDeletion(r.id));
            }
            window.customPrograms[track] = (window.customPrograms[track] || []).filter(p => (p.name || p) !== targetName);
            if (syllabusStructure[track]) {
                syllabusStructure[track] = syllabusStructure[track].filter(s => s.program !== targetName);
            }
            delete window.chartVisibility.prog[targetName]; subsToDelete.forEach(sub => delete window.chartVisibility.subjects[sub]);
            for (let i = 0; i < AppState.tasks.length; i++) {
                if (AppState.tasks[i].type !== 'study') continue;
                const key = track + 'Tasks';
                if (Array.isArray(AppState.tasks[i][key])) {
                    AppState.tasks[i][key] = AppState.tasks[i][key].map(b => subsToDelete.includes(b.subject) ? { subject: "Revision", chapter: "Rev", title: "Practice", completed: false, id: b.id } : b);
                }
            }
            if (AppState.currentFilter !== 'All') AppState.currentFilter = 'All';
            window.paceGoals = window.paceGoals.filter(g => !(g.type === 'program' && g.target === targetName) && !(g.type === 'subject' && subsToDelete.includes(g.target)));
            window.paceGoals.forEach(g => {
                if (g.type === 'bundle' && g.programs) g.programs = g.programs.filter(p => p !== targetName);
                if (g.type === 'bundle' && g.subjects) g.subjects = g.subjects.filter(s => !subsToDelete.includes(s));
            });
            window.passedItems.programs = window.passedItems.programs.filter(p => p !== targetName);
            window.passedItems.subjects = window.passedItems.subjects.filter(s => !subsToDelete.includes(s));
            if (window.revisionData.active) window.revisionData.active = window.revisionData.active.filter(s => !subsToDelete.includes(s));
            if (window.revisionData.progress) subsToDelete.forEach(sub => delete window.revisionData.progress[sub]);
            if (window.successResults) {
                window.successResults = window.successResults.filter(r => !(r.type === 'cgpa' && r.title === targetName));
            }
            showToast(`Program "${targetName}" and its subjects deleted.`, "success");

        } else if (type === 'subject') {
            if (typeof window.recordItemDeletion === 'function') {
                window.recordItemDeletion(targetName);
                (window.paceGoals || []).filter(g => g.type === 'subject' && g.target === targetName).forEach(g => window.recordItemDeletion(g.id));
                (window.successResults || []).filter(r => r.type === 'cgpa' && r.subject === targetName).forEach(r => window.recordItemDeletion(r.id));
            }
            if (syllabusStructure[track]) {
                syllabusStructure[track] = syllabusStructure[track].filter(s => s.subject !== targetName);
            }
            delete window.chartVisibility.subjects[targetName];
            for (let i = 0; i < AppState.tasks.length; i++) {
                if (AppState.tasks[i].type !== 'study') continue;
                const key = track + 'Tasks';
                if (Array.isArray(AppState.tasks[i][key])) {
                    AppState.tasks[i][key] = AppState.tasks[i][key].map(b => b.subject === targetName ? { subject: "Revision", chapter: "Rev", title: "Practice", completed: false, id: b.id } : b);
                }
            }
            if (AppState.currentFilter === targetName) AppState.currentFilter = 'All';
            window.paceGoals = window.paceGoals.filter(g => !(g.type === 'subject' && g.target === targetName));
            window.paceGoals.forEach(g => {
                if (g.type === 'bundle' && g.subjects) g.subjects = g.subjects.filter(s => s !== targetName);
            });
            window.passedItems.subjects = window.passedItems.subjects.filter(s => s !== targetName);
            if (window.revisionData.active) window.revisionData.active = window.revisionData.active.filter(s => s !== targetName);
            if (window.revisionData.progress && window.revisionData.progress[targetName]) delete window.revisionData.progress[targetName];
            if (window.successResults) {
                window.successResults = window.successResults.filter(r => !(r.type === 'cgpa' && r.subject === targetName));
            }
            showToast(`Subject "${targetName}" deleted.`, "success");
        }
    }

    recalculateTotals(); FirebaseService.saveToCloud(); renderUI(); updateManageDropdown();
};

window.resetToCleanSlate = function (confirmFirst = true) {
    const doWipe = () => {
        AppState.tracks = [];
        AppState.syllabusStructure = {};
        AppState.customPrograms = {};
        AppState.customActions = [];
        AppState.paceGoals = [];
        AppState.examSessions = [];
        AppState.examRoutine = [];
        AppState.tasks = [];
        AppState.timerLogs = [];
        AppState.scheduleBlocks = [];
        AppState.scheduleBlocks2 = [];
        AppState.scheduleGroups = [];
        AppState.weeklyTargetsDatabase = {};
        AppState.monthlyTargetsDatabase = {};
        AppState.dailyTargetsDatabase = {};
        AppState.passedItems = { programs: [], subjects: [] };
        AppState.revisionData = { active: [], progress: {} };
        AppState.subjectFocusTargets = {};
        AppState.subjectTimeLinks = {};
        AppState.successResults = [];
        AppState.programVisibility = {};
        AppState.fiscalLedger = { transactions: [], budgets: [], vaults: [] };

        AppState.dashboardConfig = {
            topTag: "X-29",
            mainTitle: "X-29 Dashboard",
            subTitle: "",
            trendStartDate: new Date().toISOString().split('T')[0],
            trendEndDate: "",
            showDaysRemaining: false,
            independentPaces: { tracks: {}, programs: {}, subjects: {} }
        };

        AppState.PLAN_START_DATE = new Date();
        AppState.PLAN_START_DATE.setHours(0, 0, 0, 0);
        AppState.PLAN_END_DATE = new Date();
        AppState.PLAN_END_DATE.setMonth(AppState.PLAN_END_DATE.getMonth() + 10);
        AppState.PLAN_END_DATE.setHours(23, 59, 59, 999);

        if (typeof safeStorage !== 'undefined') {
            try {
                safeStorage.removeItem('local_app_state');
                safeStorage.removeItem('appState');
                safeStorage.removeItem('cached_fullAppState');
                safeStorage.removeItem('cached_examSessions');
                safeStorage.removeItem('cached_examRoutine');
                safeStorage.removeItem('cached_selectedCountdownExamId');
            } catch (e) { }
        }
        try {
            if (typeof sessionStorage !== 'undefined') {
                sessionStorage.removeItem('local_app_state');
                sessionStorage.removeItem('appState');
            }
        } catch (e) { }

        if (typeof recalculateTotals === 'function') recalculateTotals();

        if (window.FirebaseService && window.FirebaseService.cloudDocumentExists !== false) {
            if (typeof window.FirebaseService.wipeCloudWorkspace === 'function') {
                window.FirebaseService.wipeCloudWorkspace();
            } else if (typeof window.FirebaseService.saveToCloud === 'function') {
                window.FirebaseService.saveToCloud(true);
            }
        }

        if (typeof renderUI === 'function') renderUI();

        if (typeof window.populateTrackDropdowns === 'function') window.populateTrackDropdowns();
        if (typeof window.updateManageDropdown === 'function') window.updateManageDropdown();
        if (typeof window.renderTrackList === 'function') window.renderTrackList();
        if (typeof window.renderExamSessions === 'function') window.renderExamSessions();

        if (typeof showToast === 'function') {
            showToast("Workspace reset successfully to a fresh, clean state!", "success");
        }
    };

    if (confirmFirst && typeof window.openConfirmModal === 'function') {
        window.openConfirmModal(
            "Reset Workspace Data",
            "Are you sure you want to completely clear all data? This will delete all tracks, subjects, chapters, daily actions, pace goals, exams, routines, tasks, and history. This action cannot be undone.",
            doWipe
        );
    } else {
        doWipe();
    }
};


